  "sim.perfume-lab.desc": "Mieszaj niezbędne olejki eteryczne i związki zapachowe, aby tworzyć charakterystyczne kompozycje i spełniać standardy jakości.",
  "sim.detergent-lab.title": "Laboratorium detergentów",
  "sim.detergent-lab.desc": "Twórz produkty do czyszczenia — dobieraj surfaktanty, wypełniacze i testy wydajności w ramach budżetu.",
  "sim.skin-care-lab.title": "Laboratorium pielęgnacji skóry",
  "sim.skin-care-lab.desc": "Opracowuj i testuj receptury kosmetyków, spełniając normy bezpieczeństwa i cele skuteczności.",
  "sim.woodworking.title": "Warsztat stolarski",
  "sim.woodworking.desc": "Prowadź własny warsztat stolarski: planuj zlecenia, zarządzaj materiałami i dostarczaj meble na czas oraz w budżecie.",
  "sim.aluminum-glazing.title": "Aluminium i przeszklenia",
  "sim.aluminum-glazing.desc": "Zarządzaj firmą zajmującą się obróbką aluminium i montażem szkła — od wyceny po zakończenie na miejscu.",
  "sim.global-kitchen.title": "Globalna Kuchnia",
  "sim.global-kitchen.desc": "Kieruj kuchnią restauracyjną: zarządzaj menu, personelem, kosztami i satysfakcją klientów we wszystkich zmianach obsługi.",
  "sim.chocolate-factory.title": "Fabryka czekolady",
  "sim.chocolate-factory.desc": "Prowadź fabrykę wyrobów cukierniczych — pozyskiwanie kakao, planowanie produkcji i kontrola jakości.",
  "sim.solar-energy.title": "Elektrownia energii słonecznej",
  "sim.solar-energy.desc": "Projektuj i obsługuj instalację fotowoltaiczną — dobieraj panele, zarządzaj eksportem do sieci i mierz ROI.",
  "sim.hvac-systems.title": "Systemy HVAC",
  "sim.hvac-systems.desc": "Instaluj i konserwuj systemy grzewcze, wentylacyjne i klimatyzacyjne dla budynków komercyjnych.",
  "sim.logistics-supply.title": "Logistyka i łańcuch dostaw",
  "sim.logistics-supply.desc": "Optymalizuj pracę magazynu, planowanie tras flot i relacje z dostawcami, aby osiągać wskaźniki KPI dostaw.",
  "sim.barber-salon.title": "Salon fryzjerski",
  "sim.barber-salon.desc": "Zarządzaj salonem fryzjerskim: rezerwacje, grafiki personelu, ceny i strategie utrzymania klientów.",
  "sim.board-surgeon.title": "Chirurg od zarządu (Board Surgeon)",
  "sim.board-surgeon.desc": "Podejmuj kluczowe decyzje chirurgiczne w symulowanej sali operacyjnej — zarządzanie czasem i bezpieczeństwo pacjentów.",
  "sim.english-journey.title": "English Journey",
  "sim.english-journey.desc": "Prowadź uczniów przez uporządkowany program nauki angielskiego, dopasowując się do różnych poziomów umiejętności.",
  "sim.music-training.title": "Studio Treningu Muzycznego",
  "sim.music-training.desc": "Prowadź szkołę muzyczną: planuj lekcje, zarządzaj instrumentami i śledź postępy uczniów w kierunku występów.",
  "sim.trade-tycoon.title": "Handlowy Tycoon",
  "sim.trade-tycoon.desc": "Buduj imperium handlowe — kupuj tanio, sprzedawaj drogo, zarządzaj zapasami i przepływem gotówki na wielu rynkach.",
  "sim.vehicle-diagnostics.title": "Symulator diagnostyki i naprawy pojazdu",
  "sim.vehicle-diagnostics.desc": "Diagnozuj kody usterek OBD-II, śledź usterki elektryczne i zarządzaj rzeczywistym procesem naprawy auta.",
  "sim.marine-vessel.title": "Śledzenie jednostek morskich i logistyka morska",
  "sim.marine-vessel.desc": "Dowodź globalną flotą — śledź jednostki, nawiguj przez zatory w portach, reaguj na sytuacje awaryjne pogodowe i opóźnienia w kanałach.",
