  "jungle.scene6": "Znalazłeś rannego ptaka. Co robisz?",
  "jungle.s6c1": "Ostrożnie go przenieś — może doprowadzić cię do ścieżki (+5 HP, +25 pkt)",
  "jungle.s6c2": "Opuść go — opieka nad nim marnuje energię (0 HP, +10 pkt)",
  "jungle.scene7": "Rzeka blokuje ci drogę. Woda wygląda na szybką.",
  "jungle.s7c1": "Zbuduj tratwę z przewróconych kłód (−5 HP, +40 pkt)",
  "jungle.s7c2": "Idź pod prąd, by znaleźć płytkie przejście (+10 HP, +20 pkt)",
  "jungle.scene8": "Widzisz w oddali dym.",
  "jungle.s8c1": "Idź w stronę dymu — może to ratunek! (+15 HP, +45 pkt)",
  "jungle.s8c2": "Unikaj — może to być pożar lasu (−5 HP, +15 pkt)",
  "jungle.scene9": "Zapada noc. Potrzebujesz schronienia.",
  "jungle.s9c1": "Wspiąć się na wysokie drzewo, by uchronić się przed drapieżnikami (+10 HP, +30 pkt)",
  "jungle.s9c2": "Zbuduj naziemne schronienie z gałęzi (−5 HP, +35 pkt)",
  "jungle.scene10": "Znalazłeś owoc, którego nie rozpoznajesz. Bardzo jesteś głodny.",
  "jungle.s10c1": "Zjedz go — głodujesz! (−20 HP, +30 pkt)",
  "jungle.s10c2": "Najpierw przetestuj mały kawałek na swojej skórze (0 HP, +20 pkt)",
  "jungle.scene11": "Na twojej drodze zwija się duży wąż.",
  "jungle.s11c1": "Cofnij się powoli i znajdź obejście (+5 HP, +30 pkt)",
  "jungle.s11c2": "Spróbuj go spłoszyć (−25 HP, +40 pkt)",
  "jungle.scene12": "Słyszysz wodospad — twoje zapasy wody są krytycznie niskie.",
  "jungle.s12c1": "Idź za dźwiękiem, by znaleźć świeżą wodę (+20 HP, +35 pkt)",
  "jungle.s12c2": "Zignoruj i idź dalej (−15 HP, +20 pkt)",
  "jungle.scene13": "Bardzo szybko nadciąga burza.",
  "jungle.s13c1": "Znajdź wyżej położone miejsce i schroń się (+10 HP, +25 pkt)",
  "jungle.s13c2": "Dalej się poruszaj, by uciec (−10 HP, +30 pkt)",
  "jungle.scene14": "Znalazłeś jaskinię. Robi się ciemno.",
  "jungle.s14c1": "Wejdź do jaskini, by się schronić (+15 HP, +30 pkt)",
  "jungle.s14c2": "Prześpij się pod drzewem — jaskinia może być zajęta (+5 HP, +20 pkt)",
  "jungle.scene15": "Jesteś wykończony. Polana przed tobą wygląda bezpiecznie.",
  "jungle.s15c1": "Odpocznij i wróć do formy (+20 HP, +20 pkt)",
  "jungle.s15c2": "Jedź dalej — odpoczynek tutaj jest niebezpieczny (−5 HP, +30 pkt)",
  "jungle.scene16": "Znalazłeś stary mapę wyrytą w drzewie.",
  "jungle.s16c1": "Idź zgodnie z kierunkiem mapy (+5 HP, +40 pkt)",
  "jungle.s16c2": "Zignoruj — może być nieaktualna (0 HP, +10 pkt)",
  "jungle.scene17": "Dzikie świnie przetaczają twoją ścieżkę agresywnie.",
  "jungle.s17c1": "Natychmiast wejdź na najbliższe drzewo (+5 HP, +30 pkt)",
  "jungle.s17c2": "Stań na swoim i krzyknij (−20 HP, +35 pkt)",
  "jungle.scene18": "Znalazłeś opuszczony obóz z zapasami.",
  "jungle.s18c1": "Weź wszystko, co się przyda (+20 HP, +50 pkt)",
  "jungle.s18c2": "Zostaw to — może ktoś będzie tego potrzebować później (0 HP, +10 pkt)",
  "jungle.scene19": "Małpa kradnie twoją torbę z jedzeniem!",
