  "legal.privacy.collect.messaging.heading": "Wiadomości z Facebook Messengera i Instagram Direct",
  "legal.privacy.collect.messaging.text": "Gdy piszesz do strony lub konta Visionex na Facebook Messengerze albo Instagram Direct, Meta przekazuje nam napisany przez Ciebie tekst, własny ograniczony identyfikator Twojej osoby (identyfikator powiązany ze stroną lub kontem na Instagramie, a nie Twój profil, adres e-mail czy numer telefonu), identyfikator wiadomości oraz czas jej wysłania. Przechowujemy te dane, aby przeczytać Twoje pytanie, zachować kolejność rozmowy, nie odpowiadać dwa razy na tę samą wiadomość i przekazać sprawę człowiekowi, gdy pomoc automatyczna nie wystarcza. Treść Twojej wiadomości jest przetwarzana przez zewnętrznych dostawców sztucznej inteligencji w celu wygenerowania odpowiedzi. Nigdy nie otrzymujemy Twojego hasła do Facebooka ani Instagrama, listy znajomych lub obserwujących, ani danych Twojego profilu.",
  "legal.privacy.third.meta.name": "Meta Platforms (Facebook Messenger, Instagram Direct, WhatsApp)",
  "legal.privacy.third.meta.purpose": "Dostarcza wiadomości wysyłane przez Ciebie do Visionex przez Messengera, Instagram Direct lub WhatsAppa oraz przekazuje Ci nasze odpowiedzi. Meta przetwarza te wiadomości na własnych platformach zgodnie z własnym regulaminem i polityką prywatności.",
  "legal.privacy.deletionLink": "Aby zażądać usunięcia danych otrzymanych z Facebook Messengera lub Instagram Direct, postępuj zgodnie z instrukcją na",
  "legal.dataDeletion.title": "Wniosek o usunięcie danych",
  "legal.dataDeletion.intro": "Ta strona wyjaśnia, jak zażądać usunięcia danych, które Visionex przechowuje na Twój temat, w tym tych otrzymanych od Meta, gdy napisałeś do nas przez Facebook Messengera lub Instagram Direct.",
  "legal.dataDeletion.howTitle": "Jak złożyć wniosek o usunięcie",
  "legal.dataDeletion.step1": "Wyślij nam wiadomość e-mail z tematem „Wniosek o usunięcie danych”.",
  "legal.dataDeletion.step2": "Wskaż, której usługi dotyczą dane — na przykład wiadomości wysłanej do strony Visionex na Facebook Messengerze lub Instagram Direct — oraz w przybliżeniu, kiedy się z nami kontaktowałeś, abyśmy mogli odnaleźć właściwą rozmowę. Jeśli masz konto Visionex, wyślij wniosek z adresu e-mail przypisanego do tego konta.",
  "legal.dataDeletion.step3": "Potwierdzamy otrzymanie wniosku, usuwamy to, co przechowujemy, i odpisujemy, informując, co zostało usunięte.",
  "legal.dataDeletion.contact": "Wnioski wysyłaj na adres",
  "legal.dataDeletion.whatTitle": "Co zostaje usunięte",
  "legal.dataDeletion.whatBody": "W przypadku Facebook Messengera i Instagram Direct usuwamy przechowywany przez nas zapis rozmowy: wysłany przez Ciebie tekst, nasze odpowiedzi, ograniczony identyfikator, który Meta przekazała nam na Twój temat, identyfikatory wiadomości i znaczniki czasu. W przypadku konta Visionex usuwamy lub anonimizujemy dane osobowe przypisane do tego konta. Nie możemy usunąć niczego, co Meta przechowuje na własnych platformach — kopia rozmowy w Twojej skrzynce Messengera lub Instagrama należy do Twojego konta Meta i możesz ją stamtąd usunąć samodzielnie.",
  "legal.dataDeletion.timingTitle": "Ile to trwa",
  "legal.dataDeletion.timingBody": "Staramy się zakończyć usuwanie w ciągu 30 dni od potwierdzenia wniosku. Tam, gdzie musimy zachować ograniczony zapis — ze względów bezpieczeństwa, przeciwdziałania oszustwom, rozstrzygania sporów lub obowiązku prawnego — przechowujemy wyłącznie to, czego to wymaga, a resztę usuwamy.",
  "legal.dataDeletion.accountTitle": "Usuwanie konta Visionex",
  "legal.dataDeletion.accountBody": "Jeśli masz konto Visionex, możesz również poprosić o jego całkowite zamknięcie, korzystając z tego samego adresu. Zamknięcie konta usuwa lub anonimizuje przypisane do niego dane osobowe, z zastrzeżeniem opisanego wyżej ograniczonego przechowywania.",
  "legal.dataDeletion.footer": "Pełne informacje o tym, co zbieramy i dlaczego, znajdziesz w",
